  return <details><summary>Record external placement</summary><form className="form-grid" onSubmit={event=>void submit(event)}><p className="span-2"><strong>External action warning:</strong> use this only after placing this one supplier order outside Koalafrog. It creates no receipt, shipment, incoming stock, or inventory.</p><label>Supplier order reference<input required value={reference} onChange={event=>setReference(event.target.value)}/></label><label>Actual currency<input required pattern="[A-Z]{3}" maxLength={3} value={currency} onChange={event=>setCurrency(event.target.value.toUpperCase())}/></label><label>Merchandise subtotal<input type="number" min="0" step=".01" value={merchandise} onChange={event=>setMerchandise(event.target.value)}/></label><label>Discount<input type="number" min="0" step=".01" value={discount} onChange={event=>setDiscount(event.target.value)}/></label><label>Shipping<input type="number" min="0" step=".01" value={shipping} onChange={event=>setShipping(event.target.value)}/></label><label>VAT<input type="number" min="0" step=".01" value={vat} onChange={event=>setVat(event.target.value)}/></label><label>Import VAT<input type="number" min="0" step=".01" value={importVat} onChange={event=>setImportVat(event.target.value)}/></label><label>Duty<input type="number" min="0" step=".01" value={duty} onChange={event=>setDuty(event.target.value)}/></label><label>Customs<input type="number" min="0" step=".01" value={customs} onChange={event=>setCustoms(event.target.value)}/></label><label>Handling<input type="number" min="0" step=".01" value={handling} onChange={event=>setHandling(event.target.value)}/></label><label>Actual grand total<input required type="number" min="0" step=".01" value={total} onChange={event=>setTotal(event.target.value)}/></label><label>Evidence reference<input value={evidence} onChange={event=>setEvidence(event.target.value)}/></label><label className="span-2">Evidence note<textarea value={evidenceNote} onChange={event=>setEvidenceNote(event.target.value)}/></label><label><input type="checkbox" checked={discountApplied} onChange={event=>setDiscountApplied(event.target.checked)}/>First-order discount applied</label><label>Discount code<input value={discountCode} onChange={event=>setDiscountCode(event.target.value)}/></label><label><input type="checkbox" checked={freeShipping} onChange={event=>setFreeShipping(event.target.checked)}/>Free shipping achieved</label><section className="span-2 scenario-line"><strong>Expected / verified / actual comparison</strong><p>Total {String(order.commercial_snapshot.estimated_total??'Unknown')} / {order.total??'Unknown'} / {total||'Unknown'} {currency}</p><p>Shipping {String(order.commercial_snapshot.shipping??'Unknown')} / {order.shipping??'Unknown'} / {shipping||'Unknown'}</p><p>Policy: {comparison.classification.replaceAll('_',' ')}</p>{comparison.warnings.map(item=><p className="candidate-warning" key={item}>{item}</p>)}{comparison.blockers.map(item=><p className="candidate-warning" key={item}>{item}</p>)}</section>{comparison.classification==='acknowledgement_required'&&<label className="span-2"><input type="checkbox" checked={acknowledged} onChange={event=>setAcknowledged(event.target.checked)}/>I explicitly acknowledge the material checkout differences.</label>}<label className="span-2"><input type="checkbox" checked={confirmed} onChange={event=>setConfirmed(event.target.checked)}/>I confirm this order was placed externally.</label><button className="button primary span-2" disabled={busy||comparison.blockers.length>0||!confirmed||(!evidence&&!evidenceNote)||(comparison.classification==='acknowledgement_required'&&!acknowledged)}>Record external placement</button></form></details>
