  return <details><summary>Create shipment record</summary><form className="form-grid" onSubmit={submit}><p className="span-2">Shipment preparation is logistics information only. It is not physical receipt or inventory.</p><label>Supplier shipment reference<input required value={reference} onChange={event=>setReference(event.target.value)}/></label><label>Carrier<input value={carrier} onChange={event=>setCarrier(event.target.value)}/></label><label>Tracking number<input value={tracking} onChange={event=>setTracking(event.target.value)}/></label><label>Tracking URL<input type="url" value={trackingUrl} onChange={event=>setTrackingUrl(event.target.value)}/></label><label>Dispatch evidence<input required value={evidence} onChange={event=>setEvidence(event.target.value)}/></label>{lines.map(line=><label key={line.id}>Ship {line.confirmed_product_identity} ({line.confirmed_quantity} {line.confirmed_package_unit} confirmed)<input type="number" min="0" max={line.confirmed_quantity} step="any" value={quantities[line.id]} onChange={event=>setQuantities(current=>({...current,[line.id]:event.target.value}))}/></label>)}<button className="button primary span-2" disabled={busy||eligible.length===0}>Create shipment</button></form></details>
