  const submit=(event:FormEvent)=>{event.preventDefault();void onSubmit({shipmentIds:selected,physicalReceiptDate:new Date().toISOString(),receivingLocation:location,packageCountExpected:null,packageCountReceived:Number(packages),outerPackagingCondition:condition,tamperState:'none_observed',waterDamageState:'none_observed',visibleContaminationState:'none_observed',temperatureConcernState:'unknown',evidenceType:'manual_reference',evidenceReference:evidence,photographReference:'',deliveryNoteReference:deliveryNote,packingSlipReference:packingSlip,sourceUrl:'',receivingNotes:notes})}
