export function ProductionReadinessPage(){
  const workspace=useActiveWorkspace(),data=useFormulaData(),navigate=useNavigate(),{roundId}=useParams()
  const[rounds,setRounds]=useState<Array<{id:string;title:string;status:string;revision:number;updated_at:string}>>([]),[aggregate,setAggregate]=useState<DurableRoundAggregate>(),[selections,setSelections]=useState<RoundProductSelection[]>(REQUIRED_PRODUCTION_CATEGORIES.map(blankSelection))
  const[title,setTitle]=useState('First production round'),[notes,setNotes]=useState(''),[message,setMessage]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false)
  const refresh=useCallback(async()=>{if(!workspace)return;try{const list=await listProductionRounds(workspace.workspaceId);setRounds(list);if(roundId){const loaded=await loadProductionRound(workspace.workspaceId,roundId);setAggregate(loaded);setTitle(loaded.round.title);setNotes(loaded.round.notes);setSelections(REQUIRED_PRODUCTION_CATEGORIES.map(category=>{const row=loaded.products.find(item=>item.category===category);return row?{category,productId:row.product_id,formulaVersionId:row.formula_version_id,batchCount:row.planned_batch_count,batchSize:row.batch_size,batchUnit:row.batch_unit,overagePercent:row.overage_percentage,expectedYield:row.expected_yield,deodorantStructure:row.deodorant_structure}:blankSelection(category)}))}else setAggregate(undefined);setError('')}catch(cause){setError(cause instanceof Error?cause.message:'Production round unavailable.')}},[workspace,roundId])
  useEffect(()=>void refresh(),[refresh])
  const updateSelection=(category:ProductionCategory,patch:Partial<RoundProductSelection>)=>setSelections(current=>current.map(item=>item.category===category?{...item,...patch}:item))
  const productOptions=useMemo(()=>Object.fromEntries(REQUIRED_PRODUCTION_CATEGORIES.map(category=>[category,data.products.filter(product=>categoryMatches(category,`${product.name} ${product.category}`))])) as Record<ProductionCategory,typeof data.products>,[data])
  const preview=selections.map(selection=>{const product=data.products.find(item=>item.id===selection.productId),formulas=data.formulas.filter(item=>item.productId===product?.id),versions=data.formulaVersions.filter(item=>formulas.some(formula=>formula.id===item.formulaId)),version=versions.find(item=>item.id===selection.formulaVersionId);const basis:RoundProductBasis|undefined=product?{product,category:selection.category,formulaVersion:version,formulaLines:data.formulaLines.filter(line=>line.formulaVersionId===version?.id),ingredients:data.ingredients,batchCount:selection.batchCount,batchSize:selection.batchSize,batchUnit:selection.batchUnit,overagePercent:selection.overagePercent,deodorantStructure:selection.category==='deodorant'?(selection.deodorantStructure as RoundProductBasis['deodorantStructure']):undefined}:undefined;return{selection,product,versions,basis,result:basis?formulaReadiness(basis):{state:'blocked' as const,reasons:[`Select the required ${labels[selection.category]} product.`]}}})
  const readyCount=preview.filter(item=>item.result.state!=='blocked').length,blockedCount=4-readyCount
  const gapsByRequirement=new Map(aggregate?.gaps.map(gap=>[gap.requirement_id,gap])??[])
  const create=async()=>{if(!workspace)return;setBusy(true);try{const id=await createProductionRound(workspace.workspaceId,'First production round');navigate(`/procurement/production-readiness/${id}`)}catch(cause){setError(cause instanceof Error?cause.message:'Could not create round.')}finally{setBusy(false)}}
  const save=async(showMessage=true)=>{if(!aggregate)return null;const revision=await saveProductionRound(aggregate.round,title,notes,selections);const updated={...aggregate.round,revision};setAggregate(current=>current?{...current,round:updated}:current);if(showMessage)setMessage(`Draft saved at revision ${revision}.`);return updated}
  const generate=async()=>{if(!aggregate)return;setBusy(true);setMessage('');try{const saved=await save(false);if(!saved)return;const revision=await regenerateProductionRound(saved);setMessage(blockedCount?`Readiness remains blocked at revision ${revision}; resolve the reasons below.`:`Requirements regenerated transactionally at revision ${revision}.`);await refresh()}catch(cause){setError(cause instanceof Error?cause.message:'Could not regenerate requirements.')}finally{setBusy(false)}}
  const cancel=async()=>{if(!aggregate||!window.confirm('Cancel this production procurement round? It will remain available for audit and cannot be regenerated.'))return;setBusy(true);try{await cancelProductionRound(aggregate.round);setMessage('Round cancelled. No inventory or purchasing records were changed.');await refresh()}catch(cause){setError(cause instanceof Error?cause.message:'Could not cancel round.')}finally{setBusy(false)}}
  const matchingAction=async(action:()=>Promise<unknown>,success:string)=>{setBusy(true);setError('');try{await action();setMessage(success);await refresh()}catch(cause){setError(cause instanceof Error?cause.message:'Supplier matching action failed.')}finally{setBusy(false)}}
  const acceptConfirmation=(confirmation:DurableOrderConfirmation,lines:DurableOrderConfirmationLine[])=>{
    const substitutions=lines.filter(line=>['substitution_requires_review','product_changed','package_changed'].includes(line.mismatch_classification))
    const compatibilityReference=substitutions.length?window.prompt('Compatibility review evidence reference (required for substitutions)')?.trim():''
    if(substitutions.length&&!compatibilityReference)return
    const decision=confirmation.classification==='exact'?'accepted_exact':substitutions.length?'accepted_commercial_difference':'accepted_partial'
    void matchingAction(
      ()=>decideSupplierConfirmation(confirmation,decision,confirmation.classification==='exact'?'':'Owner explicitly reviewed and accepted the recorded supplier differences.',lines.map(line=>({
        confirmationLineId:line.id,
        decision:'accepted',
        reason:line.mismatch_classification==='exact'?'Exact match.':'Owner explicitly reviewed the supplier difference.',
        compatibilityEvidence:substitutions.includes(line)?{reviewed:true,reference:compatibilityReference}:{},
      }))),
      'Supplier confirmation decision recorded; ordered values remain immutable.',
    )
  }
  const verify=async(item:DurablePlanVerification,state:'confirmed'|'changed'|'unavailable'|'not_applicable')=>{
    let value:unknown=item.expected_value,note='',evidence=''
    if(state==='changed'){const raw=window.prompt(`Verified value for ${item.field} (JSON or text)`,JSON.stringify(item.expected_value));if(raw==null)return;try{value=JSON.parse(raw)}catch{value=raw}}
    if(state!=='confirmed'){note=window.prompt('Verification note')??''}
    evidence=window.prompt('Evidence reference (private URL, document reference, or checkout note)')??''
    await matchingAction(()=>recordPlanVerification(item,state,value,item.expected_unit_or_currency??'',note,evidence),'Verification recorded. The immutable plan snapshot was not changed.')
  }

  if(!workspace)return <section className="panel procurement-state" role="alert"><h1>Durable workspace required</h1><p>Production Readiness is an owner-scoped Supabase workflow. Activate the Supabase workspace repository to create or reopen rounds.</p></section>
  if(!roundId)return <div className="production-readiness"><PageHeader eyebrow="Procurement / durable first-production planning" title="Production readiness rounds" description="Create or reopen an owner-controlled four-product planning round." action={<button className="button primary" disabled={busy} onClick={()=>void create()}><Plus size={15}/>New round</button>}/>{error&&<p className="form-message" role="alert">{error}</p>}<section className="readiness-round-list">{rounds.map(round=><button className="panel" key={round.id} onClick={()=>navigate(`/procurement/production-readiness/${round.id}`)}><span className="eyebrow">{round.status} · revision {round.revision}</span><strong>{round.title}</strong><small>Updated {new Date(round.updated_at).toLocaleString()}</small></button>)}{!rounds.length&&!error&&<article className="panel"><h2>No production rounds</h2><p>Create the first durable planning round. No formula selections are seeded automatically.</p></article>}</section></div>
  if(!aggregate)return <section className="panel procurement-state">{error?<><h1>Round unavailable</h1><p role="alert">{error}</p></>:<p>Loading production round…</p>}</section>
  const cancelled=aggregate.round.status==='cancelled'
  return <div className="production-readiness">
    <PageHeader eyebrow={`Procurement / durable round / revision ${aggregate.round.revision}`} title={aggregate.round.title} description="Exact formula bases, requirements, and inventory gaps persist as owner-scoped draft snapshots." action={<button className="button ghost" onClick={()=>navigate('/procurement/production-readiness')}>All rounds</button>}/>
    <div className="operational-notice"><LockKeyhole/><p>Four products are mandatory · approval creates an immutable internal plan only · checkout readiness never creates a Purchase Order, receipt, or stock.</p></div>
    {message&&<p className="form-message" role="status">{message}</p>}{error&&<p className="form-message" role="alert">{error}</p>}
    <section className="panel readiness-round-meta"><label>Round title<input value={title} disabled={cancelled} onChange={event=>setTitle(event.target.value)}/></label><label>Notes<textarea value={notes} disabled={cancelled} rows={2} onChange={event=>setNotes(event.target.value)}/></label></section>
    <section className="readiness-summary" aria-label="Round summary">
      <article><strong>4</strong><span>Required products</span></article><article><strong>{readyCount}/4</strong><span>Formula bases ready/review</span></article><article><strong>{blockedCount}</strong><span>Blocked products</span></article>
      <article><strong>{aggregate.requirements.length}</strong><span>Consolidated ingredients</span></article><article><strong>{aggregate.gaps.filter(gap=>gap.purchasing_gap>0).length}</strong><span>Purchasing gaps</span></article>
      <article><strong>{aggregate.matches.filter(item=>item.selected_supplier_product_id).length}</strong><span>Requirements selected</span></article><article><strong>{aggregate.matches.filter(item=>item.selected_supplier_product_id&&item.warnings.length).length}</strong><span>Selected with warnings</span></article><article><strong>{aggregate.candidates.filter(item=>item.classification==='exact').length}</strong><span>Exact matches</span></article><article><strong>{aggregate.matches.filter(item=>item.status==='needs_review').length}</strong><span>Research needed</span></article>
      <article><strong>{aggregate.scenarios.length}</strong><span>Scenarios generated</span></article><article><strong>{aggregate.scenarios.filter(item=>item.stale_at).length}</strong><span>Scenarios stale</span></article><article><strong>{aggregate.scenarios.find(item=>item.strategy==='balanced'&&item.status!=='published')?.supplier_count??'Unknown'}</strong><span>Balanced suppliers</span></article><article><strong>{aggregate.scenarios.find(item=>item.strategy==='balanced'&&item.status!=='published')?.unknown_commercial_components.length??0}</strong><span>Unknown cost components</span></article>
      <article><strong>{aggregate.gaps.reduce((sum,gap)=>sum+gap.net_usable_quantity,0).toFixed(2)} g</strong><span>Usable stock contribution</span></article><article><strong>{aggregate.round.last_calculated_at?new Date(aggregate.round.last_calculated_at).toLocaleString():'Not calculated'}</strong><span>Last calculated</span></article><article><strong>{aggregate.round.revision}</strong><span>Draft revision</span></article><article><strong>{aggregate.round.status.replace('_',' ')}</strong><span>Overall state</span></article>
    </section>
    <section aria-labelledby="scope-title"><header className="section-header"><div><span className="eyebrow">Durable basis</span><h2 id="scope-title">Four-product scope</h2></div></header><div className="readiness-products">{preview.map(({selection,product,versions,result})=><article className={`panel readiness-product ${result.state}`} key={selection.category}>{result.state==='ready'?<CheckCircle2/>:<AlertTriangle/>}<span className="eyebrow">{labels[selection.category]} · mandatory</span><h3>{product?.name??'Product not selected'}</h3>
      <label>Product<select disabled={cancelled} value={selection.productId??''} onChange={event=>updateSelection(selection.category,{productId:event.target.value||null,formulaVersionId:null})}><option value="">Select product</option>{productOptions[selection.category].map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label>
      <label>Formula version<select disabled={cancelled||!product} value={selection.formulaVersionId??''} onChange={event=>updateSelection(selection.category,{formulaVersionId:event.target.value||null})}><option value="">Select version</option>{versions.map(version=><option key={version.id} value={version.id}>{version.version} · {version.status}</option>)}</select></label>
      <div className="readiness-batch"><label>Batch count<input disabled={cancelled} type="number" min="1" value={selection.batchCount} onChange={event=>updateSelection(selection.category,{batchCount:Number(event.target.value)})}/></label><label>Batch size<input disabled={cancelled} type="number" min=".001" value={selection.batchSize} onChange={event=>updateSelection(selection.category,{batchSize:Number(event.target.value)})}/></label><label>Unit<select disabled={cancelled} value={selection.batchUnit} onChange={event=>updateSelection(selection.category,{batchUnit:event.target.value as RoundProductSelection['batchUnit']})}>{['mg','g','kg','ml','L','pcs'].map(unit=><option key={unit}>{unit}</option>)}</select></label><label>Overage %<input disabled={cancelled} type="number" min="0" max="100" value={selection.overagePercent} onChange={event=>updateSelection(selection.category,{overagePercent:Number(event.target.value)})}/></label></div>
      {selection.category==='deodorant'&&<label>Deodorant structure<select disabled={cancelled} value={selection.deodorantStructure??''} onChange={event=>updateSelection(selection.category,{deodorantStructure:event.target.value||null})}><option value="">Unknown — blocks generation</option>{['anhydrous','emulsion','suspension','other'].map(value=><option key={value}>{value}</option>)}</select></label>}
      <strong className="readiness-state">{result.state.replace('_',' ')}</strong>{result.reasons.length?<ul>{result.reasons.map(reason=><li key={reason}>{reason}</li>)}</ul>:<p>Composition reconciles and scales deterministically.</p>}</article>)}</div>
      {!cancelled&&<div className="readiness-actions"><button className="button ghost" disabled={busy} onClick={()=>void save()}><Save size={15}/>Save draft</button><button className="button primary" disabled={busy} onClick={()=>void generate()}><RefreshCw size={15}/>Save and regenerate</button><button className="button ghost danger" disabled={busy} onClick={()=>void cancel()}><XCircle size={15}/>Cancel round</button></div>}
    </section>
    <section aria-labelledby="requirements-title"><header className="section-header"><div><span className="eyebrow">Persisted sourcing control</span><h2 id="requirements-title">Purchasing specifications and Supplier Product matches</h2></div></header><div className="readiness-requirements">{aggregate.requirements.map(requirement=>{const gap=gapsByRequirement.get(requirement.id),spec=aggregate.specifications.find(item=>item.requirement_id===requirement.id),match=aggregate.matches.find(item=>item.requirement_id===requirement.id),candidates=aggregate.candidates.filter(item=>item.requirement_id===requirement.id),selected=aggregate.supplierProducts.find(item=>item.id===match?.selected_supplier_product_id);return <article className="panel readiness-requirement-match" key={requirement.id}><header><span className="eyebrow">Canonical ingredient · {requirement.calculation_version}</span><h3>{requirement.ingredient_name_snapshot}</h3><strong>{requirement.total_planned_quantity} {requirement.purchasing_unit}</strong><p>Purchase gap {gap?`${gap.purchasing_gap} ${gap.unit}`:'Unknown'} · readiness {requirement.state}</p><strong className="readiness-state">{match?.status.replaceAll('_',' ')??'No match selected'}</strong></header>
      <section><h4>Purchasing specification</h4>{spec?<p>INCI {String((spec.specification.inci as {value?:string|null})?.value??'Unknown')} · unit {requirement.purchasing_unit} · minimum {gap?.purchasing_gap??'Unknown'} · grade {String((spec.specification.grade as {value?:string|null})?.value??'Unknown')}</p>:<p>Unknown — generate candidates to persist the specification.</p>}</section>
      <section><h4>Selected Supplier Product</h4>{selected?<><p><strong>{selected.supplier_name} · {selected.product_name}</strong></p><p>{selected.package_quantity} {selected.package_unit} · {selected.price} {selected.currency} · {selected.availability_status??'Stock unknown'}</p><p>{match?.estimated_package_count} packs · purchased {match?.expected_purchased_quantity} {requirement.purchasing_unit} · surplus {match?.expected_surplus} {requirement.purchasing_unit}</p>{selected.product_url&&<a href={selected.product_url} target="_blank" rel="noopener noreferrer">Open product page</a>}{match?.warnings.map(warning=><p className="candidate-warning" key={warning}>Warning: {warning}</p>)}<button className="button ghost" disabled={busy||cancelled} onClick={()=>void matchingAction(()=>clearRequirementMatch(requirement.id,aggregate.round,match!.revision),'Selection cleared; no order or stock record was created.')}>Clear selection</button></>:<p>No match selected.</p>}</section>
      <section className="supplier-candidates"><header><h4>Supplier Product candidates</h4><button className="button ghost" disabled={busy||cancelled} onClick={()=>void matchingAction(()=>generateRequirementCandidates(requirement.id,aggregate.round),'Candidates generated from stored records only.')}>Generate candidates</button></header>{candidates.map(candidate=>{const product=aggregate.supplierProducts.find(item=>item.id===candidate.supplier_product_id);return <article className="supplier-candidate" key={candidate.id}><div><strong>{product?.supplier_name??'Unknown supplier'} · {product?.product_name??candidate.supplier_product_id}</strong><span className="status-pill">{candidate.status==='rejected'?'Rejected':candidate.classification.replaceAll('_',' ')}</span><p>Score {candidate.score} · {String(candidate.package_snapshot.size??'Unknown')} {String(candidate.package_snapshot.unit??'')} · {product?.price??'Unknown'} {product?.currency??''}</p>{candidate.match_reasons.map(reason=><p key={reason}>Match: {reason}</p>)}{candidate.mismatch_reasons.map(reason=><p className="candidate-warning" key={reason}>Mismatch: {reason}</p>)}{candidate.warnings.map(warning=><p className="candidate-warning" key={warning}>Warning: {warning}</p>)}<p>Documentation: SDS {String(candidate.documentation_snapshot.sds??'unknown')} · COA {String(candidate.documentation_snapshot.coa??'unknown')}</p><p>Freshness: price {String(candidate.freshness_snapshot.price??'unknown')} · stock {String(candidate.freshness_snapshot.stock??'unknown')}</p>{product?.product_url&&<a href={product.product_url} target="_blank" rel="noopener noreferrer">Direct link</a>}</div><div className="candidate-actions"><button className="button ghost" disabled={busy||cancelled||candidate.status==='rejected'} onClick={()=>void matchingAction(()=>acceptSupplierProductMapping(requirement.id,candidate.supplier_product_id,aggregate.round),'Canonical mapping accepted; the round selection remains unchanged.')}>Accept mapping</button><button className="button primary" disabled={busy||cancelled||candidate.status==='rejected'||!candidate.mapping_id||['incompatible','unit_incompatible','unavailable','missing_mapping'].includes(candidate.classification)} onClick={()=>void matchingAction(()=>selectRequirementCandidate(requirement.id,candidate.id,aggregate.round,match?.revision??1),'Supplier Product selected for this requirement; nothing was ordered.')}>Select</button><button className="button ghost danger" disabled={busy||cancelled||candidate.status==='rejected'} onClick={()=>{const reason=window.prompt('Why is this candidate unsuitable?');if(reason)void matchingAction(()=>rejectRequirementCandidate(candidate.id,aggregate.round,reason),'Candidate rejected for this requirement only.')}}>Reject</button><button className="button ghost" disabled={busy||cancelled||!match} onClick={()=>match&&void matchingAction(()=>clearRequirementMatch(requirement.id,aggregate.round,match.revision,'Needs research'),'Requirement marked as needing research.')}>Needs research</button></div></article>})}{!candidates.length&&<p>No candidates generated. This does not trigger external research.</p>}</section>
    </article>})}{!aggregate.requirements.length&&<article className="panel"><ShoppingBasket/><h3>Not calculated</h3><p>Save the four exact formula bases, then regenerate. Calculated zero and unknown are never displayed as the same state.</p></article>}</div></section>
    <section aria-labelledby="scenarios-title"><header className="section-header"><div><span className="eyebrow">Commercial planning snapshots</span><h2 id="scenarios-title">Basket scenarios</h2><p>Six deterministic views over the exact selected Supplier Products. Publishing freezes comparison history; it is not purchase approval.</p></div><button className="button primary" disabled={busy||cancelled} onClick={()=>void matchingAction(()=>generateProductionScenarios(aggregate.round),'Basket scenarios generated from stored commercial records only.')}>Generate or regenerate scenarios</button></header>
      <div className="scenario-grid">{aggregate.scenarios.map(scenario=>{const baskets=aggregate.scenarioBaskets.filter(item=>item.scenario_id===scenario.id),lines=aggregate.scenarioLines.filter(item=>item.scenario_id===scenario.id),activePlan=aggregate.purchasePlans.find(item=>['verification_required','checkout_ready'].includes(item.status));return <article className="panel scenario-card" key={scenario.id}><header><span className="eyebrow">{scenario.status} · {scenario.calculation_version}</span><h3>{strategyLabels[scenario.strategy]??scenario.strategy}</h3><strong className="readiness-state">{scenario.stale_at?'Stale':scenario.mixed_currency?'Mixed currency':scenario.feasibility.replaceAll('_',' ')}</strong></header><dl><div><dt>Suppliers / lines</dt><dd>{scenario.supplier_count} / {scenario.line_count}</dd></div><div><dt>Known minimum</dt><dd>{scenario.total_known_minimum==null?'Incomplete':`${scenario.total_known_minimum} ${scenario.base_currency}`}</dd></div><div><dt>Confirmed total</dt><dd>{scenario.total_confirmed==null?'Unknown':`${scenario.total_confirmed} ${scenario.base_currency}`}</dd></div><div><dt>Estimated total</dt><dd>{scenario.total_estimated==null?'Unknown':`${scenario.total_estimated} ${scenario.base_currency}`}</dd></div><div><dt>Warnings / blockers</dt><dd>{scenario.warning_count} / {scenario.blocker_count}</dd></div><div><dt>Unknown components</dt><dd>{scenario.unknown_commercial_components.join(', ')||'None'}</dd></div></dl>{scenario.ranking_explanation.map(reason=><p key={reason}>{reason}</p>)}<details><summary>View supplier baskets and lines</summary>{baskets.map(basket=><section className="scenario-basket" key={basket.id}><h4>{basket.supplier_name_snapshot} · {basket.currency}</h4><p>Merchandise {basket.merchandise_subtotal} · confirmed discount {basket.confirmed_discount} · estimated discount {basket.estimated_discount}</p><p>Shipping {basket.shipping==null?basket.shipping_state:basket.shipping} · VAT {basket.vat_state} · import {basket.import_vat_state} · customs {basket.customs_state} · handling {basket.handling_state}</p><p>Known minimum {basket.known_minimum} · confirmed {basket.confirmed_total??'Unknown'} · estimated {basket.estimated_total??'Unknown'}</p>{lines.filter(line=>line.basket_id===basket.id).map(line=><article className="scenario-line" key={line.id}><strong>{line.ingredient_name_snapshot} · {line.supplier_product_name_snapshot}</strong><p>Gap {line.required_quantity} {line.required_unit} · {line.package_count} × {line.package_size} {line.package_unit} · purchased {line.purchased_quantity} · surplus {line.surplus}</p><p>Line {line.merchandise_line_total} {line.currency} · discount {line.allocated_discount} · shipping {line.allocated_shipping??'Unknown'} · effective unit cost {line.effective_cost_per_required_unit??'Unknown'}</p>{line.product_url_snapshot&&<a href={line.product_url_snapshot} target="_blank" rel="noopener noreferrer">Direct product link</a>}</article>)}</section>)}</details>{scenario.unknown_commercial_components.length>0&&<div className="candidate-actions" aria-label="Commercial research handoff">{['Refresh price','Verify stock','Verify shipping','Verify Norway delivery','Verify first-order discount','Verify tax/import assumption'].map(label=><button className="button ghost" key={label} onClick={()=>navigate('/procurement')}>{label}</button>)}</div>}{scenario.status!=='published'&&<button className="button ghost" disabled={busy||scenario.feasibility==='incomplete'||scenario.feasibility==='blocked'} onClick={()=>void matchingAction(()=>publishProductionScenario(scenario,aggregate.round),'Scenario snapshot published for comparison history; no plan or order was created.')}>Publish comparison snapshot</button>}{isScenarioApprovable(scenario)&&!aggregate.purchasePlans.some(item=>item.source_scenario_id===scenario.id)&&<button className="button primary" disabled={busy} onClick={()=>{if(activePlan&&!window.confirm(`Supersede purchase plan v${activePlan.plan_version} with this published scenario?`))return;void matchingAction(()=>approveProductionScenario(scenario,activePlan?.id),'Immutable purchase plan approved. Verify current checkout facts before marking it ready.')}}>Approve immutable plan</button>}</article>})}{!aggregate.scenarios.length&&<article className="panel"><h3>No basket scenarios</h3><p>Select a valid Supplier Product for every purchasing gap, then generate. Missing shipping, tax, import, or currency facts remain unknown.</p></article>}</div>
    </section>
    <section aria-labelledby="purchase-plans-title"><header className="section-header"><div><span className="eyebrow">Approval boundary</span><h2 id="purchase-plans-title">Immutable purchase plans</h2><p>Supplier-neutral plan headers group frozen supplier baskets. Verification records current checkout facts without rewriting the approved snapshot.</p></div></header>
      <div className="scenario-grid">{aggregate.purchasePlans.map(plan=>{const baskets=aggregate.planBaskets.filter(item=>item.purchase_plan_id===plan.id),checks=aggregate.planVerifications.filter(item=>item.purchase_plan_id===plan.id),audit=aggregate.planAuditEvents.filter(item=>item.purchase_plan_id===plan.id),orders=aggregate.draftOrders.filter(item=>item.source_purchase_plan_id===plan.id),gate=purchasePlanGate(checks.map(item=>({severity:item.severity,verificationState:item.verification_state,resolutionState:item.resolution_state})));return <article className="panel scenario-card purchase-plan-card" key={plan.id}><header><span className="eyebrow">Plan v{plan.plan_version} · snapshot {plan.snapshot_version}</span><h3>{plan.title}</h3><strong className="readiness-state">{plan.status.replaceAll('_',' ')}</strong></header><p>{strategyLabels[plan.strategy]??plan.strategy} · {plan.supplier_count} suppliers · {plan.line_count} lines</p><p>Known minimum {plan.known_minimum??'Unknown'} {plan.base_currency} · estimated landed {plan.estimated_landed_total??'Unknown'}</p>{baskets.map(basket=><details key={basket.id}><summary>{basket.supplier_name_snapshot} · {basket.verification_completed_count}/{basket.verification_required_count} checks resolved</summary>{aggregate.planLines.filter(line=>line.purchase_plan_basket_id===basket.id).map(line=><p key={line.id}><strong>{line.ingredient_name_snapshot}</strong> · {line.pack_count} × {line.pack_size} {line.unit} · {line.estimated_line_total} {line.currency} {safeExternalUrl(line.product_url_snapshot)&&<a href={safeExternalUrl(line.product_url_snapshot)!} target="_blank" rel="noopener noreferrer">Product</a>}</p>)}</details>)}<div className="plan-verifications">{checks.map(item=><article className={`scenario-line verification-${item.resolution_state}`} key={item.id}><strong>{item.category.replaceAll('_',' ')} · {item.field.replaceAll('_',' ')}</strong><p>{item.requirement_reason}</p><p>Expected: {JSON.stringify(item.expected_value)} {item.expected_unit_or_currency??''} · state: {item.verification_state.replaceAll('_',' ')}</p>{!['superseded','cancelled'].includes(plan.status)&&<div className="candidate-actions"><button className="button ghost" disabled={busy} onClick={()=>void verify(item,'confirmed')}>Confirm</button><button className="button ghost" disabled={busy} onClick={()=>void verify(item,'changed')}>Record change</button><button className="button ghost" disabled={busy} onClick={()=>void verify(item,'unavailable')}>Unavailable</button><button className="button ghost" disabled={busy} onClick={()=>void verify(item,'not_applicable')}>Not applicable</button>{canWaiveVerification(item.severity)&&<button className="button ghost" disabled={busy} onClick={()=>{const reason=window.prompt('Reason for advisory waiver');if(reason)void matchingAction(()=>waivePlanVerification(item,reason),'Advisory check waived with an audit reason.')}}>Waive advisory</button>}</div>}</article>)}</div><details><summary>Audit history · {audit.length} events</summary>{audit.map(event=><p key={event.id}><strong>{event.event_type.replaceAll('_',' ')}</strong> · {new Date(event.occurred_at).toLocaleString()}<br/>{event.reason}</p>)}</details>{plan.status==='verification_required'&&<button className="button primary" disabled={busy||!gate.ready} onClick={()=>void matchingAction(()=>markPlanCheckoutReady(plan),'Plan marked checkout ready. No Purchase Order, receipt, movement, or stock was created.')}><ClipboardCheck size={15}/>Mark checkout ready</button>}{plan.status==='checkout_ready'&&orders.length===0&&<><p><strong>Draft handoff ready:</strong> {baskets.length} suppliers · {baskets.length} internal drafts · {aggregate.planLines.filter(item=>item.purchase_plan_id===plan.id).length} lines. No external checkout will occur.</p><button className="button primary" disabled={busy} onClick={()=>{if(window.confirm(`Create ${baskets.length} internal draft Purchase Orders for ${baskets.length} suppliers? No external checkout, payment, receipt, or inventory action will occur.`))void matchingAction(()=>createDraftPurchaseOrders(plan),`${baskets.length} internal draft Purchase Orders created. Nothing was placed externally.`)}}>Create draft Purchase Orders</button></>}{orders.map(order=>{const lines=aggregate.draftOrderLines.filter(item=>item.purchase_order_id===order.id),supplier=String(order.supplier_snapshot.displayName??'Supplier');return <article className="scenario-line" key={order.id}><strong>{supplier} · Internal draft · {order.status==='draft'?'Not placed':'Cancelled'}</strong><p>Source Plan v{order.source_purchase_plan_version} · {lines.length} lines · {order.currency}</p><p>Merchandise {order.merchandise_subtotal??'Unknown'} · discount {order.discount??'Unknown'} · shipping {order.shipping??'Unknown'} · total {order.total??'Unknown'}</p>{lines.map(line=><p key={line.id}>{line.ingredient_name_snapshot} · {line.ordered_package_count} packs · Expected {line.expected_unit_price??'Unknown'} · Verified {line.verified_unit_price??'same as expected'} · Effective {line.effective_unit_price??'Unknown'} {line.currency} {safeExternalUrl(line.product_url_snapshot)&&<a href={safeExternalUrl(line.product_url_snapshot)!} target="_blank" rel="noopener noreferrer">Open product</a>}</p>)}<details><summary>Manual ordering checklist</summary><ul>{order.manual_checkout_checklist.map(item=><li key={item}>{item}</li>)}</ul><p>Completing this checklist does not place the order.</p></details>{safeExternalUrl(order.supplier_url_snapshot)&&<a href={safeExternalUrl(order.supplier_url_snapshot)!} target="_blank" rel="noopener noreferrer">Open supplier</a>}{order.status==='draft'&&<button className="button ghost danger" disabled={busy} onClick={()=>{const reason=window.prompt('Why is this unplaced draft cancelled?');if(reason)void matchingAction(()=>cancelDraftPurchaseOrder(order,reason),'Draft cancelled. Its immutable snapshot remains available.')}}>Cancel draft</button>}</article>})}{!['superseded','cancelled'].includes(plan.status)&&<button className="button ghost danger" disabled={busy} onClick={()=>{const reason=window.prompt('Why is this internal plan cancelled?');if(reason)void matchingAction(()=>cancelInternalPlan(plan,reason),'Internal plan cancelled; its snapshot and audit history remain intact.')}}>Cancel plan</button>}<button className="button ghost" onClick={()=>navigate('/procurement')}>Open procurement research</button></article>})}{!aggregate.purchasePlans.length&&<article className="panel"><h3>No approved purchase plan</h3><p>Publish a feasible scenario, then approve it explicitly. Approval does not order anything.</p></article>}</div>
    </section>
    {aggregate.draftOrders.length>0&&<section aria-labelledby="order-execution-title">
      <header className="section-header"><div><span className="eyebrow">Supplier execution · one order at a time</span><h2 id="order-execution-title">Purchase Order confirmation and shipment</h2><p>Supplier responses and reported logistics remain separate from physical receipt, inspection, lots, movements, and available stock.</p></div></header>
      <div className="readiness-summary" aria-label="Purchase Order execution summary"><article><strong>{aggregate.draftOrders.filter(item=>item.status==='placed').length}</strong><span>Awaiting confirmation</span></article><article><strong>{aggregate.confirmations.filter(item=>item.lifecycle_status==='recorded').length}</strong><span>Current confirmations</span></article><article><strong>{aggregate.shipments.filter(item=>item.status==='preparing').length}</strong><span>Preparing shipments</span></article><article><strong>{aggregate.shipments.filter(item=>['dispatched','in_transit','delivery_reported'].includes(item.status)).length}</strong><span>Reported in logistics</span></article></div>
      <div className="scenario-grid">{aggregate.draftOrders.map(order=>{
        const lines=aggregate.draftOrderLines.filter(item=>item.purchase_order_id===order.id),supplier=String(order.supplier_snapshot.displayName??'Supplier')
        const confirmations=aggregate.confirmations.filter(item=>item.purchase_order_id===order.id),current=confirmations.find(item=>item.lifecycle_status==='recorded')
        const confirmationLines=current?aggregate.confirmationLines.filter(item=>item.confirmation_id===current.id):[]
        const shipments=aggregate.shipments.filter(item=>item.purchase_order_id===order.id)
        const receipts=aggregate.receipts.filter(item=>item.purchase_order_id===order.id)
        return <article className="panel scenario-card placement-order-card" key={order.id}><header><span className="eyebrow">Purchase Order · Plan v{order.source_purchase_plan_version}</span><h3>{supplier}</h3><strong className="readiness-state">{order.status.replaceAll('_',' ')}</strong></header>
          <p>Expected / verified / placed total: {String(order.commercial_snapshot.estimated_total??'Unknown')} / {order.total??'Unknown'} / {order.actual_grand_total??'Not placed'} {order.actual_currency??order.currency}</p>
          {order.status==='draft'&&<PlacementForm order={order} lines={lines} busy={busy} onSubmit={payload=>matchingAction(()=>recordVerifiedPurchaseOrderPlacement(order,payload),'External placement recorded. No receipt, shipment, or inventory was created.')}/>}
          {order.status!=='draft'&&order.status!=='cancelled'&&<section className="scenario-line"><strong>Placed externally</strong><p>Supplier reference {order.order_reference} · evidence {String(order.placement_evidence.reference??order.placement_evidence.note??'Unknown')}</p><p><strong>No receiving yet. No inventory yet.</strong> Placement and supplier execution are not receipt or inventory.</p></section>}
          {!['draft','cancelled'].includes(order.status)&&<ConfirmationForm order={order} lines={lines} busy={busy} onSubmit={payload=>matchingAction(()=>recordSupplierConfirmation(order,payload),'Supplier confirmation recorded. Placement snapshots remain unchanged; no shipment or inventory was created.')}/>}
          {confirmations.map(confirmation=>{const recordedLines=aggregate.confirmationLines.filter(item=>item.confirmation_id===confirmation.id);return <section className="scenario-line" key={confirmation.id}><strong>Confirmation v{confirmation.confirmation_version} · {confirmation.lifecycle_status}</strong><p>{confirmation.supplier_confirmation_reference} · {confirmation.classification.replaceAll('_',' ')} · decision {confirmation.acceptance_status.replaceAll('_',' ')}</p><p>Confirmed total {confirmation.confirmed_grand_total} {confirmation.confirmed_currency} · evidence {confirmation.evidence_reference}</p>{recordedLines.map(line=><p key={line.id}>{line.confirmed_product_identity} · ordered {line.ordered_package_count}, confirmed {line.confirmed_package_count} packs · {line.availability_state.replaceAll('_',' ')} · {line.mismatch_classification.replaceAll('_',' ')} · decision {line.owner_decision}</p>)}
            {confirmation.lifecycle_status==='recorded'&&confirmation.acceptance_status==='pending_decision'&&<div className="candidate-actions"><button className="button primary" disabled={busy} onClick={()=>acceptConfirmation(confirmation,recordedLines)}>Accept reviewed confirmation</button><button className="button ghost danger" disabled={busy} onClick={()=>void matchingAction(()=>decideSupplierConfirmation(confirmation,'replanning_required','Supplier exception requires explicit replanning.',recordedLines.map(line=>({confirmationLineId:line.id,decision:'replanning_required',reason:'Requires replanning.',compatibilityEvidence:{}}))),'Confirmation marked for replanning; the Purchase Plan was not changed.')}>Reject differences and replan</button></div>}
          </section>})}
          {current?.acceptance_status.startsWith('accepted_')&&<ShipmentForm order={order} lines={confirmationLines} busy={busy} onSubmit={payload=>matchingAction(()=>createOrderShipment(order,current,payload),'Shipment preparation recorded. No Receipt, lot, movement, or stock was created.')}/>}
          {shipments.map((shipment:DurableOrderShipment)=><section className="scenario-line" key={shipment.id}><strong>Shipment {shipment.shipment_sequence} · {shipment.status.replaceAll('_',' ')}</strong><p>{shipment.carrier||'Carrier unknown'} · tracking {shipment.tracking_number||'not recorded'} {safeExternalUrl(shipment.tracking_url)&&<a href={safeExternalUrl(shipment.tracking_url)!} target="_blank" rel="noopener noreferrer">Open tracking</a>}</p>{aggregate.shipmentLines.filter(item=>item.shipment_id===shipment.id).map(line=><p key={line.id}>Shipped {line.shipped_quantity} {line.package_unit} · remaining {line.backordered_remainder}</p>)}{shipment.status==='preparing'&&<button className="button primary" disabled={busy} onClick={()=>void matchingAction(()=>recordShipmentStatus(shipment,'dispatched',{dispatchDate:new Date().toISOString(),carrier:shipment.carrier,trackingNumber:shipment.tracking_number,evidenceType:'manual_reference',evidenceReference:shipment.evidence_reference}),'Dispatch explicitly recorded. Goods are still not received.')}>Record dispatch</button>}{!['delivery_reported','cancelled'].includes(shipment.status)&&<button className="button ghost" disabled={busy} onClick={()=>void matchingAction(()=>recordShipmentStatus(shipment,'delivery_reported',{reportedAt:new Date().toISOString(),evidenceType:'manual_reference',evidenceReference:shipment.evidence_reference}),'Carrier-reported delivery recorded. Physical receipt and inspection remain unrecorded.')}>Record delivery reported</button>}{shipment.status==='delivery_reported'&&<p className="candidate-warning"><strong>Carrier reports delivery. Physical receipt and inspection have not been recorded.</strong></p>}</section>)}
          {shipments.some(item=>['dispatched','in_transit','delayed','carrier_exception','delivery_reported','physically_received'].includes(item.status))&&<ReceiptForm shipments={shipments} busy={busy} onSubmit={payload=>matchingAction(()=>createOrderReceipt(order,payload),'Physical arrival recorded. Contents remain unapproved and unavailable.')}/>}
          {receipts.map(receipt=>{const receivedLines=aggregate.receiptLines.filter(item=>item.receipt_id===receipt.id),discrepancies=aggregate.receiptDiscrepancies.filter(item=>item.receipt_id===receipt.id),inspections=aggregate.receiptInspections.filter(item=>item.receipt_id===receipt.id),intakes=aggregate.quarantineIntakes.filter(item=>item.receipt_id===receipt.id),linkedShipmentIds=aggregate.receiptShipments.filter(item=>item.receipt_id===receipt.id).map(item=>item.shipment_id),availableShipmentLines=aggregate.shipmentLines.filter(item=>linkedShipmentIds.includes(item.shipment_id));return <section className="scenario-line" key={receipt.id}><strong>Receipt {receipt.receipt_sequence} · {receipt.status.replaceAll('_',' ')}</strong><p>Physically received {receipt.package_count_received} packages at {receipt.receiving_location} · evidence {receipt.evidence_reference}</p><p><strong>Not released · Not available for production.</strong></p>
            {receipt.status!=='quarantined'&&receipt.status!=='cancelled'&&<ReceiptLineForm receipt={receipt} orderLines={lines} shipmentLines={availableShipmentLines} busy={busy} onSubmit={payload=>matchingAction(()=>recordOrderReceiptLine(receipt,payload),'Physical receipt line recorded; no inventory was created.')}/>}
            {receivedLines.map(line=><article className="scenario-line" key={line.id}><strong>{line.received_product_name} · {line.line_status.replaceAll('_',' ')}</strong><p>Ordered {line.ordered_quantity} · confirmed {line.confirmed_quantity??'Unknown'} · shipped {line.shipped_quantity??'Unknown'} · physically received {line.received_total_quantity} {line.received_package_unit}</p><p>Damaged {line.damaged_quantity} · held {line.held_quantity} · rejected {line.rejected_quantity} · quarantine candidate {line.quarantine_candidate_quantity} · outstanding {Math.max(0,(line.shipped_quantity??line.confirmed_quantity??line.ordered_quantity)-line.received_total_quantity)}</p><p>Supplier lot {line.supplier_lot_number||'Missing'} · expiry {line.expiry_date??'Not recorded'} · identity {line.identity_status} · condition {line.condition_status}</p>
              <div className="candidate-actions"><button className="button ghost danger" disabled={busy} onClick={()=>{const description=window.prompt('Describe the discrepancy');if(description)void matchingAction(()=>recordReceiptDiscrepancy(receipt,{receiptLineId:line.id,discrepancyType:'damaged_item',severity:'major',affectedQuantity:line.damaged_quantity||line.held_quantity||1,unit:line.received_package_unit,description,evidence:{reference:receipt.evidence_reference},supplierResponsibilityState:'unknown',ownerDisposition:'hold_for_review',reason:description,supplierClaimRequired:false}),'Receipt discrepancy appended; no supplier claim was created.' )}}>Record discrepancy</button><button className="button ghost" disabled={busy} onClick={()=>void matchingAction(()=>recordReceiptInspection(receipt,{receiptLineId:line.id,inspectionType:'identity_and_label',result:line.identity_status==='matches'?'passed_receiving_checks':'conditional_hold',checklistSnapshot:{identityStatus:line.identity_status,conditionStatus:line.condition_status,documentation:line.documentation_checks},measuredValues:{},notes:'Owner-recorded receiving inspection.',evidence:{reference:receipt.evidence_reference}}),'Receiving inspection appended; material remains unavailable.')}>Record inspection</button></div>
            </article>)}
            {discrepancies.map(item=><p key={item.id}><strong>Discrepancy:</strong> {item.discrepancy_type.replaceAll('_',' ')} · {item.severity} · {item.owner_disposition.replaceAll('_',' ')} · {item.resolution_status}</p>)}
            {inspections.map(item=><p key={item.id}><strong>Inspection v{item.inspection_version}:</strong> {item.inspection_type.replaceAll('_',' ')} · {item.result.replaceAll('_',' ')}</p>)}
            {['receiving','inspection_pending','inspection_in_progress','discrepancy_review'].includes(receipt.status)&&receivedLines.length>0&&<button className="button primary" disabled={busy} onClick={()=>void matchingAction(()=>completeOrderReceiving(receipt),'Receiving checks completed. Quarantine eligibility was evaluated without releasing inventory.')}>Complete receiving checks</button>}
            {['quarantine_ready','discrepancy_review'].includes(receipt.status)&&receivedLines.some(line=>line.quarantine_candidate_quantity>0)&&<button className="button primary" disabled={busy} onClick={()=>void matchingAction(()=>quarantineOrderReceipt(receipt,{lines:receivedLines.filter(line=>line.quarantine_candidate_quantity>0).map(line=>({receiptLineId:line.id,quarantineQuantity:line.quarantine_candidate_quantity,containerCount:line.received_package_count,quarantineLocation:'Receiving quarantine area',quarantineReason:'Receiving checks completed; awaiting quality release.',storageRequirementSnapshot:{},hazardSnapshot:{}}))}),'Eligible quantities placed into quarantine. They are not released or available for production.')}>Place eligible quantity into quarantine</button>}
            {intakes.map(item=><p className="candidate-warning" key={item.id}><strong>Quarantined · Not released · Not available:</strong> {item.quarantine_quantity} {item.unit} · lot {item.supplier_lot_number} · {item.quarantine_location}</p>)}
          </section>})}
          <details><summary>Audit history · {aggregate.draftOrderAuditEvents.filter(item=>item.purchase_order_id===order.id).length} events</summary>{aggregate.draftOrderAuditEvents.filter(item=>item.purchase_order_id===order.id).map(event=><p key={event.id}>{event.event_type.replaceAll('_',' ')} · {new Date(event.occurred_at).toLocaleString()}</p>)}</details>
        </article>
      })}</div>
    </section>}
  </div>
}
